input.sparql:
SELECT ?point ?point_uri ?tid WHERE {
  ?point brick:hasPropertyType ?ptype .
  ?ptype a brick:ElectricPower .
  ?point ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?tid .
}

SELECT ?p (STR(?p) as ?pu) WHERE {
  ?p a brick:PowerSensor .
}
LIMIT 50

SELECT ?pt (STR(?pt) as ?ptu) ?label ?eq (STR(?eq) as ?equ) WHERE {
  ?pt a brick:Power_Sensor .
  ?pt rdfs:label ?label .
  OPTIONAL { ?eq brick:hasPoint ?pt }
}
LIMIT 100

SELECT ?pt (STR(?pt) as ?ptu) ?label ?eq (STR(?eq) as ?equ) WHERE {
  ?pt a brick:Electric_Power_Sensor .
  ?pt rdfs:label ?label .
  OPTIONAL { ?eq brick:hasPoint ?pt }
}
LIMIT 100

SELECT ?p ?o (STR(?p) as ?ps) (STR(?o) as ?os) WHERE {
  ?p a brick:Electric_Power_Sensor .
  ?p ?s ?o .
}
LIMIT 200
